async function readUser(id) {
  const hit = await cache.get('user:' + id);
  if (hit) return hit;                      // cache hit
  const row = await db.queryUser(id);
  await cache.set('user:' + id, row, 3600); // 1h TTL
  return row;
}

async function updateUser(id, patch) {
  const next = { ...(await db.queryUser(id)), ...patch };
  await cache.set('user:' + id, next, 3600); // update cache first
  await db.updateUser(id, patch);            // then persist
  return next;
}
